import argparse
import json
import os

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("json_file", help="JSON data file")
    parser.add_argument("command", choices=["add", "list", "remove"], help="Command to execute")
    parser.add_argument("name", nargs="?", help="Name of the bookmark")
    parser.add_argument("url", nargs="?", help="URL of the bookmark")
    args = parser.parse_args()

    if not os.path.exists(args.json_file):
        print("Error: JSON file not found")
        return

    with open(args.json_file, "r") as file:
        bookmarks = json.load(file)

    if args.command == "add":
        if not args.name or not args.url:
            print("Error: Missing name or URL")
            return
        bookmarks[args.name] = args.url
    elif args.command == "list":
        for name, url in sorted(bookmarks.items(), key=lambda item: item[0]):
            print(f"{name}\t{url}")
    elif args.command == "remove":
        if not args.name:
            print("Error: Missing name")
            return
        if args.name not in bookmarks:
            print("Error: Bookmark not found")
            return
        del bookmarks[args.name]
    else:
        print("Error: Invalid command")

if __name__ == "__main__":
    main()

import sys
import argparse
import csv
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--category", help="Filter by category")
    args = parser.parse_args()
    category = args.category

    expenses = []
    for row in csv.DictReader(sys.stdin):
        if category and row["category"] != category:
            continue
        expenses.append(row)

    if not expenses:
        print("No expenses found")
        return

    grouped_expenses = {}
    for expense in expenses:
        category = expense["category"]
        amount = float(expense["amount"])
        if category not in grouped_expenses:
            grouped_expenses[category] = []
        grouped_expenses[category].append(amount)

    result = {}
    for category, amounts in grouped_expenses.items():
        result[category] = "{:.2f}".format(sum(amounts))

    print(json.dumps(result, indent=4))


if __name__ == "__main__":
    main()

import sys

def main():
    board = [" " for _ in range(9)]
    current_player = "X"
    game_over = False

    def print_board():
        print("-------------")
        for i in range(3):
            print("|", board[i*3], board[i*3+1], board[i*3+2], "|")
        print("-------------")

    def check_winner():
        winning_combinations = [
            (0, 1, 2), (3, 4, 5), (6, 7, 8),
            (0, 3, 6), (1, 4, 7), (2, 5, 8),
            (0, 4, 8), (2, 4, 6)
        ]
        for combination in winning_combinations:
            if board[combination[0]] == board[combination[1]] == board[combination[2]] != " ":
                return board[combination[0]]
        return None

    while not game_over:
        print_board()
        try:
            move = int(input(f"Player {current_player}, enter your move (1-9): "))
            if move < 1 or move > 9 or board[move-1] != " ":
                raise ValueError("Invalid move")
            board[move-1] = current_player
        except ValueError as e:
            print(e)
            continue

        winner = check_winner()
        if winner:
            print_board()
            print(f"{winner} wins!")
            game_over = True
        elif " " not in board:
            print_board()
            print("Draw")
            game_over = True
        else:
            current_player = "O" if current_player == "X" else "X"

if __name__ == "__main__":
    main()

import argparse
import json
import os

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", help="directory to inventory")
    parser.add_argument("--suffix", help="suffix to filter files by")
    args = parser.parse_args()

    inventory = inventory_directory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

def inventory_directory(directory, suffix=None):
    inventory = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            if suffix and not file.endswith(suffix):
                continue
            path = os.path.join(root, file)
            inventory[path] = os.path.getsize(path)
    return inventory

if __name__ == "__main__":
    main()

import argparse
import json
import sys


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=argparse.FileType("r"), help="JSONL file with transactions")
    args = parser.parse_args()

    total_cents = 0
    for line_number, line in enumerate(args.input, start=1):
        try:
            transaction = json.loads(line)
            if not isinstance(transaction, dict) or "id" not in transaction or "cents" not in transaction:
                raise ValueError("Invalid transaction format")
            if not isinstance(transaction["id"], str) or not isinstance(transaction["cents"], int):
                raise ValueError("Invalid transaction values")
            if transaction["id"] == "":
                raise ValueError("Transaction id cannot be empty")
            if transaction["cents"] <= 0:
                raise ValueError("Transaction cents must be positive")
            total_cents += transaction["cents"]
        except json.JSONDecodeError:
            print(f"Error decoding line {line_number}: {line}", file=sys.stderr)
            return 1
        except ValueError as e:
            print(f"Error in line {line_number}: {e}", file=sys.stderr)
            return 1

    print(total_cents)
    return 0


if __name__ == "__main__":
    sys.exit(main())

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <json_file>")
        return

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print(f"Error: {json_file} not found")
        return

    if not isinstance(data, list) or not all(isinstance(item, dict) for item in data):
        print("Error: JSON file is not valid")
        return

    score = 0
    for item in data:
        if not all(key in item for key in ["question", "answer"]):
            print(f"Error: Question or answer missing in item {item}")
            return

        question = item["question"].strip()
        answer = item["answer"].strip().lower()

        print(question)
        for line in sys.stdin:
            user_answer = line.strip().lower()
            if user_answer == answer:
                score += 1
                break

    print(f"Score: {score}/{len(data)}")

if __name__ == "__main__":
    main()
